// A list read from its operation a page at a time through api.call,
// sorted, searched and filtered by the service, drawn through the table
// component the ui-components idiom names, with its row actions, each
// offered while its rule holds for the row and its permission is held: one
// runs an operation on the row after its confirmation, and one opens a
// page with its route filled from the row.

import { api } from "../api.js";
import { decide } from "./access.js";
import { Confirm, runAction } from "./Confirm.js";
import { leave } from "./Notice.js";
import { fillRoute, Link, location } from "./router.js";
import { evaluate, refusalOf } from "./rules.js";
import { useSession } from "./session.js";
import { Table } from "./table.js";
import { say } from "./texts.js";
import { h, html, reactive, watch } from "./vue.js";

function text(value) {
  return value === null || value === undefined ? "" : String(value);
}

export const ListPage = {
  name: "ListPage",
  props: { schema: { type: Object, required: true }, texts: { type: Object, required: true }, routes: { type: Object, required: true } },
  setup(props) {
    const session = useSession();
    const state = reactive({
      page: 1,
      pageSize: props.schema.pageSize,
      sort: null,
      search: "",
      filters: {},
      shown: props.schema.columns.map((column) => column.field),
      reload: 0,
      result: undefined,
      failed: "",
      confirming: undefined,
      reason: "",
      running: false,
      latest: "",
    });

    /** The query the list is read with, by the wire names; filtered says whether a filter or a search narrows it. */
    function request() {
      const { schema } = props;
      const query = {};
      for (const filter of schema.filters) {
        const value = state.filters[filter.field] ?? "";
        if (value !== "") {
          query[filter.query] = value;
        }
      }
      if (state.search !== "") {
        query[schema.wire.search] = state.search;
      }
      const filtered = Object.keys(query).length > 0;
      if (state.sort !== null) {
        query[schema.wire.sort] = (state.sort.descending ? "-" : "") + state.sort.field;
      }
      query[schema.wire.page] = String(state.page);
      query[schema.wire.pageSize] = String(state.pageSize);
      return { query, filtered, key: JSON.stringify(query) + "#" + state.reload };
    }

    watch(
      () => request().key,
      (key) => {
        const { schema, texts } = props;
        const { query } = request();
        state.latest = key;
        api
          .call(schema.source.operation, { query, list: schema.wire })
          .then(async (response) => {
            const answer = response.ok ? await api.body(response) : undefined;
            if (state.latest !== key) {
              return;
            }
            const items = api.property(answer, schema.wire.items);
            if (!response.ok || !Array.isArray(items)) {
              state.result = { key, rows: [], totalItems: 0, failed: say(texts, refusalOf(schema.failed, response.status)?.message ?? "screens.failed") };
              return;
            }
            const totalPages = Number(api.property(answer, schema.wire.totalPages) ?? 0);
            if (items.length === 0 && state.page > 1 && totalPages > 0 && state.page > totalPages) {
              state.page = totalPages; // the page asked for is past the last
              return;
            }
            state.result = { key, rows: items, totalItems: Number(api.property(answer, schema.wire.totalItems) ?? 0) };
          })
          .catch(() => {
            if (state.latest === key) {
              state.result = { key, rows: [], totalItems: 0, failed: say(texts, "screens.failed") };
            }
          });
      },
      { immediate: true },
    );

    const holds = (permission) => session.value !== undefined && session.value !== null && decide(permission, session.value) === "allowed";
    const offered = (row) => props.schema.rowActions.filter((action) => holds(action.permission) && (action.when === undefined || evaluate(action.when, row) === true));

    function sortBy(field) {
      const current = state.sort;
      if (current === null || current.field !== field) {
        state.sort = { field, descending: false };
      } else {
        state.sort = current.descending ? null : { field, descending: true };
      }
      state.page = 1;
    }

    function applyFilters(event) {
      event.preventDefault();
      const form = new FormData(event.currentTarget);
      state.filters = Object.fromEntries(props.schema.filters.map((filter) => [filter.field, String(form.get(filter.field) ?? "").trim()]));
      state.page = 1;
    }

    async function run(action, row) {
      if (action.reason !== undefined && state.reason.trim() === "") {
        return;
      }
      state.running = true;
      const refused = await runAction(action, row, state.reason, props.texts);
      if (refused === undefined && action.signIn !== undefined) {
        try {
          const { signIn } = await import("../identity-provider.js");
          await signIn();
          return;
        } catch (error) {
          state.failed = error instanceof Error ? error.message : String(error);
        }
      } else if (refused === undefined) {
        state.failed = "";
        if (action.message !== undefined) {
          leave(say(props.texts, action.message), location.value.path);
        }
        state.reload += 1;
      } else {
        state.failed = refused;
      }
      state.running = false;
      state.confirming = undefined;
      state.reason = "";
    }

    function start(action, row) {
      state.reason = "";
      if (action.confirm === undefined) {
        void run(action, row);
      } else {
        state.confirming = { action, row };
      }
    }

    return () => {
      const { schema, texts, routes } = props;
      const { filtered, key } = request();
      const loading = state.result?.key !== key;
      const rows = state.result?.rows ?? [];
      const totalItems = state.result?.totalItems ?? 0;
      const totalPages = Math.max(1, Math.ceil(totalItems / state.pageSize));
      const message = state.result?.failed ?? (state.result && rows.length === 0 ? say(texts, filtered ? schema.filteredEmpty : schema.empty) : "");
      const columns = schema.columns.filter((column) => state.shown.includes(column.field)).map((column) => ({ field: column.field, title: say(texts, column.title), sortable: column.sortable, compact: column.compact }));
      const first = schema.columns[0]?.field ?? "";
      const cell = ({ row, column }) =>
        column.field === columns[0]?.field && schema.select !== undefined
          ? h(Link, { to: fillRoute(routes[schema.select.navigate] ?? "/", row, schema.select.with) }, () => text(row[column.field]))
          : text(row[column.field]);
      const actions = ({ row }) => {
        const given = offered(row);
        if (given.length === 0) {
          return null;
        }
        return h(
          "ul",
          { class: "screens-row-actions", "aria-label": say(texts, "screens.actions") + " " + text(row[first]) },
          given.map((action) =>
            h(
              "li",
              { key: action.label },
              "navigate" in action
                ? h(Link, { to: fillRoute(routes[action.navigate] ?? "/", row, action.with) }, () => say(texts, action.label))
                : h("button", { type: "button", class: "screens-link", onClick: () => start(action, row) }, say(texts, action.label)),
            ),
          ),
        );
      };
      const slots = { cell };
      if (schema.rowActions.length > 0) {
        slots.actions = actions;
      }
      return html`<section class="screens-list">
        <h1>${say(texts, schema.title)}</h1>
        ${state.failed !== "" ? html`<p role="alert" class="screens-problem">${state.failed} <button type="button" class="screens-close" aria-label="×" onClick=${() => (state.failed = "")}>×</button></p>` : null}
        ${schema.filters.length > 0
          ? html`<form class="screens-filters" onSubmit=${applyFilters}>
              ${schema.filters.map((filter) =>
                filter.options !== undefined
                  ? html`<label key=${filter.field}>${say(texts, filter.title)}
                      <select id=${"filter-" + filter.field} name=${filter.field}>
                        <option value="">${say(texts, "screens.any")}</option>
                        ${filter.options.map((option) => html`<option key=${option} value=${option}>${option}</option>`)}
                      </select>
                    </label>`
                  : html`<label key=${filter.field}>${say(texts, filter.title)} <input id=${"filter-" + filter.field} name=${filter.field} type=${filter.date ? "date" : "text"} /></label>`,
              )}
              <button type="submit" class="screens-secondary">${say(texts, "screens.filter")}</button>
            </form>`
          : null}
        <div class="screens-toolbar" role="toolbar" aria-label=${say(texts, schema.title)}>
          ${schema.search
            ? html`<label class="screens-search">${say(texts, "screens.search")}
                <input type="search" value=${state.search} onInput=${(event) => {
                  state.search = event.target.value;
                  state.page = 1;
                }} />
              </label>`
            : null}
          <details class="screens-columns">
            <summary>${say(texts, "screens.columns")}</summary>
            ${schema.columns.map(
              (column) => html`<label key=${column.field} class="screens-checkbox"><input type="checkbox" checked=${state.shown.includes(column.field)} onChange=${(event) => {
                state.shown = event.target.checked ? schema.columns.map((c) => c.field).filter((f) => f === column.field || state.shown.includes(f)) : state.shown.filter((f) => f !== column.field);
              }} /> ${say(texts, column.title)}</label>`,
            )}
          </details>
          <button type="button" class="screens-secondary" onClick=${() => (state.reload += 1)}>${say(texts, "screens.refresh")}</button>
          ${schema.actions.filter((action) => holds(action.permission)).map((action) => html`<${Link} key=${action.navigate} class="screens-button" to=${routes[action.navigate]}>${say(texts, action.label)}<//>`)}
        </div>
        <${Table} columns=${columns} rows=${rows} sort=${state.sort} rowKey=${(row, index) => text(row[first]) + "-" + index} label=${say(texts, schema.title)} actionsLabel=${say(texts, "screens.actions")} onSort=${sortBy}>${slots}<//>
        ${loading ? html`<p role="status" class="screens-loading">${say(texts, "screens.loading")}</p>` : null}
        ${!loading && message !== "" ? html`<p role="status" class=${state.result?.failed !== undefined ? "failed" : undefined}>${message}</p>` : null}
        <nav class="screens-pages" aria-label=${say(texts, { text: "screens.page", count: state.page })}>
          <button type="button" class="screens-secondary" disabled=${state.page <= 1} onClick=${() => (state.page -= 1)}>${say(texts, "screens.previous")}</button>
          <span>${say(texts, { text: "screens.page", count: state.page })}</span>
          <button type="button" class="screens-secondary" disabled=${state.page >= totalPages} onClick=${() => (state.page += 1)}>${say(texts, "screens.next")}</button>
          <label>${say(texts, "screens.pageSize")}
            <select value=${String(state.pageSize)} onChange=${(event) => {
              state.pageSize = Number(event.target.value);
              state.page = 1;
            }}>
              ${schema.pageSizes.map((size) => html`<option key=${size} value=${String(size)}>${size}</option>`)}
            </select>
          </label>
        </nav>
        ${state.confirming !== undefined && state.confirming.action.confirm !== undefined
          ? html`<${Confirm}
              action=${state.confirming.action}
              texts=${texts}
              reason=${state.reason}
              running=${state.running}
              onReason=${(reason) => (state.reason = reason)}
              onConfirm=${() => void run(state.confirming.action, state.confirming.row)}
              onClose=${() => (state.confirming = undefined)}
            />`
          : null}
      </section>`;
    };
  },
};
